import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

// 相对脚本自身定位 .gen/，与执行命令时的工作目录无关
const genDir = fileURLToPath(new URL('../.gen', import.meta.url));

// 空清单：无代码场景的默认产物（ensure-entry 在任何构建/类型检查前运行，
// 因此 src 对 .gen 的静态引用永远有东西可解析）。真实清单由
// `scripts/gen-active-scenes.mjs` 按当前作品整体覆盖。
const ACTIVE_SCENES_EMPTY =
  "// Generated by material2video; do not edit.\n" +
  "import type { M2VCodeScene } from '@/code-scene';\n" +
  "\n" +
  "// 当前作品没有代码场景：分镜全部走场景树解释器。\n" +
  "export const ACTIVE_CODE_SCENES: Record<string, M2VCodeScene<any>> = {};\n";

// Tailwind source 索引的空产物：无代码场景时没有额外扫描目标。
// 真实索引由 `scripts/gen-active-scenes.mjs` 按当前作品整体覆盖。
const ACTIVE_TAILWIND_EMPTY =
  "/* Generated by material2video; do not edit. */\n" +
  "/* 当前作品没有代码场景：Tailwind 不扫描任何作品目录。 */\n";

function ensure(file, content) {
  if (!fs.existsSync(file)) {
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content, 'utf8');
  }
}

// composition 不再由构建期入口写死：契约页与 Remotion 根都按分镜声明的
// 契约版本在运行时选择 composition，一次构建因此能服务任意作品。
ensure(path.join(genDir, 'active-scenes.ts'), ACTIVE_SCENES_EMPTY);
ensure(path.join(genDir, 'active-tailwind.css'), ACTIVE_TAILWIND_EMPTY);
